// Spring WebFlux + Project Reactor: streaming order updates
@GetMapping(value = "/orders/{id}/updates",
            produces = MediaType.TEXT_EVENT_STREAM_VALUE)
public Flux<OrderUpdate> streamOrderUpdates(@PathVariable String id) {
    return orderEventSource
        .getUpdates(id)                // Publisher<OrderUpdate>
        .filter(u -> !u.isInternal())  // drop internal state
        .delayElements(Duration.ofMillis(50))  // throttle
        .onBackpressureBuffer(100);    // buffer up to 100 if client slow
    // Subscriber (browser/client) controls demand via SSE protocol
}

import { featureFlags } from './flags';

// Feature toggle checked at runtime — no deploy to change
async function processCheckout(userId: string, cart: Cart) {
  const useNewPricingEngine = await featureFlags.isEnabled(
    'new-pricing-engine',
    { userId }           // targeting: evaluate per user
  );

  const price = useNewPricingEngine
    ? await newPricingService.calculate(cart)
    : await legacyPricingService.calculate(cart);

  return completeCheckout(userId, cart, price);
}
